func (r *Runtime) waitReady(
	ctx context.Context,
	name, namespace string,
	timeout time.Duration,
) error {
	effectiveTimeout := r.timeoutFor(timeout)
	waitCtx, cancel := context.WithTimeout(ctx, effectiveTimeout)
	defer cancel()

	var lastState *clablabruntime.LabState
	settledWithStopped := false
	readinessProgress := nodeReadinessProgress{}
	imageProgress := imagePullProgress{}
	phaseProgress := nodePhaseProgress{}
	log.Info("Waiting for C9s lab to become ready", "name", name, "namespace", namespace)

	err := wait.PollUntilContextCancel(waitCtx, pollInterval, true,
		func(ctx context.Context) (bool, error) {
			state, err := r.Inspect(ctx, clablabruntime.InspectRequest{
				Name:      name,
				Namespace: namespace,
			})
			if err != nil {
				// client-go's rate limiter can refuse a request shortly before the context
				// expires with "would exceed context deadline". Let the poller return the
				// authoritative timeout instead of masking it with that implementation detail.
				if ctx.Err() != nil || contextDeadlineIsImminent(ctx) {
					return false, nil
				}

				return false, fmt.Errorf("failed to inspect clabernetes lab %s/%s: %w",
					namespace, name, err)
			}
			lastState = state
			imageProgress.observe(ctx, r, namespace, state)
			phaseProgress.observe(ctx, r, name, namespace)
			readinessProgress.report(state)

			if state.Ready {
				return true, nil
			}
			if settled, err := r.labSettledWithStoppedNodes(ctx, state); err != nil {
				return false, err
			} else if settled {
				settledWithStopped = true
				return true, nil
			}
			if failure := phaseProgress.terminalFailure(); failure != "" {
				return false, fmt.Errorf(
					"clabernetes lab %s/%s cannot be deployed: %s",
					namespace, name, failure)
			}
			if state.State == "deployfailed" {
				return false, fmt.Errorf("clabernetes topology %s/%s reported deployfailed",
					namespace, name)
			}

			log.Debug("Waiting for C9s lab",
				"name", name,
				"namespace", namespace,
				"state", state.State,
			)

			return false, nil
		})
	if err == nil {
		if !settledWithStopped {
			log.Info("C9s lab is ready", "name", name, "namespace", namespace)
		}

		return nil
	}
	if !errors.Is(err, context.DeadlineExceeded) {
		return err
	}

	pendingNodes := make([]string, 0)
	if lastState != nil {
		for _, node := range lastState.Nodes {
			if node.Ready {
				continue
			}
			state := node.State
			if state == "" {
				state = "unknown"
			}
			pendingNodes = append(pendingNodes, fmt.Sprintf("%s (%s)", node.Name, state))
		}
	}

	if len(pendingNodes) == 0 {
		return fmt.Errorf(
			"timed out after %s waiting for clabernetes lab %s/%s to become ready",
			effectiveTimeout,
			namespace,
			name,
		)
	}

	return fmt.Errorf(
		"timed out after %s waiting for clabernetes lab %s/%s to become ready; "+
			"pending nodes: %s",
		effectiveTimeout,
		namespace,
		name,
		strings.Join(pendingNodes, ", "),
	)
}

// labSettledWithStoppedNodes reports whether a lab with stopped nodes reached the state an
// apply can reach: every node is ready, stopped on purpose, or up and only waiting for stopped
// link peers. A lab without stopped nodes is settled only when it is ready.
func (r *Runtime) labSettledWithStoppedNodes(
	ctx context.Context,
	state *clablabruntime.LabState,
) (bool, error) {
	hasStopped := false
	for _, node := range state.Nodes {
		if node.State == "stopped" || node.State == "stopping" {
			hasStopped = true
		}
	}
	if !hasStopped {
		return false, nil
	}

	states, err := r.labRunStates(ctx, state.Name, state.Namespace)
	if err != nil {
		if ctx.Err() != nil || contextDeadlineIsImminent(ctx) {
			return false, nil
		}

		return false, err
	}

	notes := make([]string, 0)
	for _, node := range state.Nodes {
		if node.Ready {
			continue
		}
		settled, reason := states.settledNode(node.Name)
		if !settled {
			return false, nil
		}
		notes = append(notes, fmt.Sprintf("%s (%s)", node.Name, reason))
	}

	log.Info("C9s lab is ready apart from stopped nodes", "name", state.Name,
		"namespace", state.Namespace, "nodes", strings.Join(notes, ", "))

	return true, nil
}

type trackedNodeReadiness struct {
	state string
	ready bool
}

type nodeReadinessProgress struct {
	nodes map[string]trackedNodeReadiness
}

func (p *nodeReadinessProgress) report(state *clablabruntime.LabState) {
	if state == nil {
		return
