		nodeState := node.State
		if nodeState == "" {
			nodeState = "unknown"
		}
		log.Info(
			"C9s node is not ready",
			"node", node.Name,
			"state", nodeState,
			"ready", readyCount,
			"total", len(state.Nodes),
		)
	}

	p.nodes = next
}

func contextDeadlineIsImminent(ctx context.Context) bool {
	deadline, ok := ctx.Deadline()

	return ok && time.Until(deadline) <= pollInterval
